#define BSNN_FLAG_DEFAULT                 (0x0800)
#define BSNN_FLAG_DISABLE_AUTO_FLUSH      (0x0001)   /* disable auto flush input data                */
#define BSNN_FLAG_DISABLE_AUTO_INVLD      (0x0002)   /* disable auto invalidate output data          */
#define BSNN_FLAG_ENABLE_WEIGHT_ON_OCM    (0x0004)   /* enable weight on ocm                         */
#define BSNN_FLAG_ENABLE_BUFFER_OUTSIDE   (0x0010)   /* ebable spill user setting                    */
#define BSNN_FLAG_ENABLE_WEIGHT_OUTSIDE   (0x0020)   /* enable weight user setting                   */
#define BSNN_FLAG_ENABLE_LIBRVV_OUTSIDE   (0x0040)   /* enable rvv user setting                      */
#define BSNN_FLAG_ENABLE_LIBDSP_OUTSIDE   (0x0080)   /* enable dsp user setting                      */
#define BSNN_FLAG_ENABLE_FENCE_IN         (0x0100)   /* enable fence in                              */
#define BSNN_FLAG_ENABLE_FENCE_OUT        (0x0200)   /* enable fence out                             */
#define BSNN_FLAG_QUICK_MODE              (0x0800)   /* quick mode: auto close all debug             */

#define BSNN_FLAG_ENABLE_MEM_CONTIGUOUS (0x1000) /* enable cma                                   */
#define BSNN_FLAG_ENABLE_MEM_SECURE     (0x2000) /* enable secure mem, can't be accessed by user */
#define BSNN_FLAG_ENABLE_MEM_NON_CACHE  (0x4000) /* enable non cache                             */
#define BSNN_FLAG_ENABLE_MEM_DMA32      (0x8000)
#define BSNN_FLAG_ENABLE_OCM            (0xAAAA) /* only used for mem_create_with_flag api       */

#define BSNN_FLAG_MASK                  (0xFFFF)

#define BSNN_FLAG_PRIORITY_MASK         (0x0007)   /* ctx priority, 0 ~ 7 is supported             */

#define BSNN_MEM_SYNC_TO_DEVICE         (1UL << 0) /* sync to   device, aka. flush cache           */
#define BSNN_MEM_SYNC_FROM_DEVICE       (1UL << 1) /* sync from device, aka. invalidate cahe       */

/* memory type maybe unsed to user */
#define BSNN_MEM_DIR_IN                    0x01      /* input  memory                                */
#define BSNN_MEM_DIR_OUT                   0x02      /* output memory                                */
